 private const string Api="/api/quality/investigations";
 private static string Day(int offset)=>DateTime.UtcNow.AddDays(offset).ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);
 private static long Id(JsonElement response)=>long.Parse(response.GetProperty("entityId").GetString()!,CultureInfo.InvariantCulture);
 private static async Task<JsonElement> Json(HttpResponseMessage response){var text=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {text}");using var parsed=JsonDocument.Parse(text);return parsed.RootElement.Clone();}
 private static async Task Reject(SlittingPlant.Plant plant,HttpClient actor,string path,object body,string code,HttpStatusCode expected=HttpStatusCode.UnprocessableEntity){using var response=await plant.Try(actor,path,body);Assert.Equal(expected,response.StatusCode);Assert.Contains(code,await response.Content.ReadAsStringAsync(),StringComparison.OrdinalIgnoreCase);}
 private static async Task<string> Stored(ForgeApp app,string table,string where,long id)
 {await using var connection=new NpgsqlConnection(app.ConnectionString);await connection.OpenAsync();await using var command=new NpgsqlCommand($"SELECT COALESCE(jsonb_agg(to_jsonb(trace_actual_row) ORDER BY to_jsonb(trace_actual_row)::text)::text,'[]') FROM {table} trace_actual_row WHERE {where}=$1",connection);command.Parameters.AddWithValue(id);return(string)(await command.ExecuteScalarAsync())!;}
 private static async Task<(SlittingPlant.Plant Plant,long Order,long Shipment,long? Inspection,Guid? Program)> Source(ForgeApp app,bool measured=false,bool privateOutput=false)
 {
  var(plant,planner)=await SlittingPlant.BuildEngineeredAsync(app);await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People["eng"]}/roles",new{role=Roles.QualityEngineer,reason="Actual measurement finding/trace investigator"});await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People["approver"]}/roles",new{role=Roles.QualityManager,reason="Independent human impact/finding review"});
  await plant.Ok(plant.Admin,"/api/kernel/roles",new{role="TraceOwnerSourceRead",displayName="Explicit read of actual investigation owner sources",permissions=new[]{Permissions.PurchasingRead,Permissions.WorkforceRead,Permissions.MaterialPlanRead},reason="Read authority is explicit; no product release or stock authority granted"});
  foreach(var person in new[]{"eng","approver"})await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People[person]}/roles",new{role="TraceOwnerSourceRead",reason="Actual source read for human investigation"});
  await plant.Person("trace-buyer",Roles.Buyer);await plant.Person("trace-purchase-approver",Roles.PurchasingManager);await plant.Person("trace-inspector",Roles.Inspector,"TraceOwnerSourceRead");await plant.Person("trace-shipper",Roles.Shipper);await plant.Person("trace-terminal",Roles.ShopFloorTerminal);await plant.Person("trace-planner",Roles.Planner);
  foreach(var(part,unit,makeBuy) in new[]{("TRACE-RAW","KG","Buy"),("TRACE-OUTPUT","EA","Make")}){await plant.Ok(plant.Engineer,"/api/engineering/items",new{partNumber=part,description=part,unitOfMeasure=unit,makeBuy,leadTimeDays=1,lotTracked=true});await plant.Ok(plant.Engineer,$"/api/engineering/items/{part}/revisions",new{revision="A"});}
  await plant.Ok(plant.Engineer,"/api/engineering/items/TRACE-OUTPUT/revisions/A/bom",new{lineNumber=1,componentPartNumber="TRACE-RAW",quantityPer=1,scrapPercent=0});
  await plant.Ok(plant.Engineer,"/api/engineering/items/TRACE-OUTPUT/revisions/A/routing",new{sequence=10,description="Actual trace assembly",workCenterCode="ASSY-WC",activityCode="ASSEMBLE",setupMinutes=0,runMinutesPerUnit=1,crewSize=1});
  foreach(var part in new[]{"TRACE-RAW","TRACE-OUTPUT"})await plant.Ok(plant.Approver,$"/api/engineering/items/{part}/revisions/A/release",new{reason="Actual approved configuration"});
  await plant.Ok(plant.As("trace-buyer"),"/api/procurement/suppliers",new{code="TRACE-MILL",name="Actual recorded supplier"});var po=Id(await plant.Ok(plant.As("trace-buyer"),"/api/procurement/purchase-orders",new{supplier="TRACE-MILL",lines=new[]{new{partNumber="TRACE-RAW",quantity=20,promisedDate=Day(3)}}}));await plant.Ok(plant.As("trace-purchase-approver"),$"/api/procurement/purchase-orders/{po}/approve",new{reason="Independent actual purchasing source"});
  await plant.Ok(plant.As("stores"),"/api/inventory/receipts",new{partNumber="TRACE-RAW",quantity=20,locationCode="STORES",lotNumber="MASTER",supplierLot="ACTUAL-MILL-LOT",poNumber=po,poLine=1,revision="A",reason="Actual external lot into existing ledger"});
  await plant.Ok(plant.As("stores"),"/api/inventory/splits",new{partNumber="TRACE-RAW",lotNumber="MASTER",locationCode="STORES",status="Released",results=new[]{new{lotNumber="CHILD",quantity=10}},reason="Actual recorded child of supplier lot"});
  Guid? program=null;
  if(privateOutput)
  {await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People["eng"]}/roles",new{role=Roles.ProgramManager,reason="Create actual private downstream source"});program=Guid.Parse((await plant.Ok(plant.Engineer,"/api/programs/",new{code="TRACE-PRIVATE",name="Private actual trace output"})).GetProperty("entityId").GetString()!);foreach(var person in new[]{"eng","approver","planner","stores","dana","trace-inspector","trace-terminal","trace-shipper","trace-planner"})await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People[person]}/programs",new{programId=program,reason="Explicit actual manufacturing source access"});}
  if(measured){await plant.Ok(plant.Engineer,"/api/quality/gauges",new{code="TRACE-GAUGE",description="Actual measuring resource",calibrationDue=Day(10),certificate="Observed original passing certificate",reason="Actual recorded calibration"});await plant.Ok(plant.Engineer,"/api/quality/plans",new{partNumber="TRACE-OUTPUT",sequence=10,title="Actual width inspection",revision="A",characteristics=new[]{new{name="Width",kind="Variable",nominal=10,lower=9,upper=11,unit="mm"}},reason="Actual approved legacy inspection arrangement"});}
  var order=Id(await plant.Ok(planner,"/api/orders/",new{partNumber="TRACE-OUTPUT",programId=program,quantity=10,dueDate=Day(5),priority=1,reason="Actual source-linked order"}));await plant.Ok(plant.As("trace-planner"),$"/api/orders/{order}/release",new{reason="Actual production order"});await plant.Ok(plant.As("stores"),"/api/inventory/issues",new{orderNumber=order,partNumber="TRACE-RAW",quantity=10,locationCode="STORES",lotNumber="CHILD",reason="Exact actual issued child material"});
  await plant.Ok(plant.Admin,$"/api/workforce/people/{plant.People["dana"]}/badge",new{badge="TRACE-DANA"});await plant.Ok(plant.As("trace-terminal"),"/api/shopfloor/clock-in",new{badge="TRACE-DANA"});await plant.Ok(plant.As("trace-terminal"),"/api/shopfloor/start",new{badge="TRACE-DANA",orderNumber=order,sequence=10});await plant.Ok(plant.As("trace-terminal"),"/api/shopfloor/report",new{badge="TRACE-DANA",orderNumber=order,sequence=10,good=10,scrap=0,complete=true});
  long? inspection=null;if(measured)inspection=Id(await plant.Ok(plant.As("trace-inspector"),"/api/quality/inspections",new{orderNumber=order,sequence=10,quantity=10,gaugeCode="TRACE-GAUGE",findings=new[]{new{number=1,measured=10}},reason="Actual independent observed product measurement"}));
  await plant.Ok(plant.As("stores"),"/api/inventory/production-receipts",new{orderNumber=order,quantity=10,locationCode="STORES",lotNumber="ACTUAL-OUTPUT",reason="Actual source-linked output; no governed release adoption invented"});
  var demand=Id(await plant.Ok(planner,"/api/planning/demand",new{partNumber="TRACE-OUTPUT",quantity=10,needDate=Day(5),kind="CustomerOrder",customer="Recorded actual customer",programId=program,reason="Actual customer-order source"}));
  var shipment=Id(await plant.Ok(plant.As("stores"),"/api/inventory/shipments",new{customer="Recorded actual customer",demandId=demand,lines=new[]{new{partNumber="TRACE-OUTPUT",lotNumber="ACTUAL-OUTPUT",quantity=10,locationCode="STORES"}},reason="Exact recorded customer-order shipment"}));await plant.Ok(plant.As("stores"),$"/api/inventory/shipments/{shipment}/pack",new{reason="Actual recorded physical packing"});await plant.Ok(plant.As("trace-shipper"),$"/api/inventory/shipments/{shipment}/ship",new{carrier="Observed carrier",tracking="TRACE-ACTUAL",reason="Actual shipment after ordinary owner checks"});
  return(plant,order,shipment,inspection,program);
 }
 private static async Task<TraceInvestigationView> View(HttpClient actor,long id,int? snapshot=null)=>await actor.GetFromJsonAsync<TraceInvestigationView>(Api+"/trace/"+id+(snapshot is{} number?"?snapshot="+number:string.Empty),CanonicalJson.Options)??throw new InvalidOperationException("Investigation view missing.");
 [Fact]
 public async Task Actual_supplier_lot_traces_child_material_output_real_labor_shipment_customer_order_and_independent_hold_review()
 {
  await using var app=new ForgeApp(await postgres.CreateDatabaseAsync(),configureBuilder:builder=>builder.UseSetting(QmsService.ConfigurationKey,"EXAMPLE-ORG"));var(plant,order,shipment,_,_)=await Source(app);
  await plant.Ok(plant.As("stores"),"/api/inventory/splits",new{partNumber="TRACE-RAW",lotNumber="MASTER",locationCode="STORES",status="Released",results=new[]{new{lotNumber="TRACE-STAGE-RAW",quantity=5},new{lotNumber="TRACE-PENDING-SHIP",quantity=5}},reason="Actual supplier lot descendants for allocated and staged-shipment impact"});
  await plant.Ok(plant.As("stores"),"/api/inventory/locations",new{code="TRACE-STAGE",siteCode="PLANT1",name="Actual staging destination",kind="Staging",workCenterCode="ASSY-WC",reason="Actual source-linked material staging location"});
  var allocatedOrder=Id(await plant.Ok(plant.As("planner"),"/api/orders/",new{partNumber="TRACE-OUTPUT",quantity=5,dueDate=Day(6),priority=2,reason="Actual downstream order for allocated suspect material"}));await plant.Ok(plant.As("trace-planner"),$"/api/orders/{allocatedOrder}/release",new{reason="Independent release of the actual downstream order"});
  var allocatedTask=Id(await plant.Ok(plant.As("stores"),"/api/inventory/tasks",new{kind="Stage",orderNumber=allocatedOrder,partNumber="TRACE-RAW",quantity=5,toLocation="TRACE-STAGE",fromLocation="STORES",lotNumber="TRACE-STAGE-RAW",reason="Actual lot allocation to unreleased downstream production"}));
  var pendingDemand=Id(await plant.Ok(plant.As("planner"),"/api/planning/demand",new{partNumber="TRACE-RAW",quantity=5,needDate=Day(4),kind="CustomerOrder",customer="Recorded staged customer",reason="Actual pending customer demand for the descendant lot"}));
  var pendingShipment=Id(await plant.Ok(plant.As("stores"),"/api/inventory/shipments",new{customer="Recorded staged customer",demandId=pendingDemand,lines=new[]{new{partNumber="TRACE-RAW",lotNumber="TRACE-PENDING-SHIP",quantity=5,locationCode="STORES"}},reason="Actual customer shipment allocation before departure"}));await plant.Ok(plant.As("stores"),$"/api/inventory/shipments/{pendingShipment}/pack",new{reason="Actual packed but not departed descendant shipment"});
  var body=new{root=new TraceInvestigationRoot(TraceTriggerKind.SupplierLot,"TRACE-RAW","MASTER",null),title="Actual supplier-lot investigation",ownerPersonId=plant.People["eng"],triggerEvidence="Actual supplier lot concern reported and retained",reason="Human opened trace investigation; no automatic defect"};
  var result=await Json(await plant.Engineer.CommandAsync(Api+"/trace",body,"actual-supplier-case"));var id=Id(result);var view=await View(plant.Engineer,id);
  Assert.True(view.Snapshot.Capture.Completeness.RecordedTraversalComplete);Assert.False(view.Snapshot.Capture.Completeness.ConcurrentSnapshotUncertain);Assert.False(string.IsNullOrWhiteSpace(view.Snapshot.Capture.Boundary.SnapshotIdentity));Assert.Equal(view.Snapshot.Capture.Boundary.CapturedAt,view.Snapshot.Capture.DataCutoff);
  Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Lot"&&c.PartNumber=="TRACE-RAW"&&c.LotNumber=="CHILD"&&c.Revision=="A");Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Order"&&c.OrderNumber==order);Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Worker"&&c.RecordId==plant.People["dana"].ToString());Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Shipment"&&c.ShipmentId==shipment&&c.Status=="Shipped");Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.Category=="CustomerOrder");
  Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.Category=="CurrentStock"&&c.RecordType=="StockBalance"&&c.LotNumber=="TRACE-STAGE-RAW"&&c.Quantity==5&&c.Status=="Released");Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="MaterialTask"&&c.RecordId==allocatedTask.ToString(CultureInfo.InvariantCulture)&&c.OrderNumber==allocatedOrder&&c.Status=="Allocated");Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.Category=="PlannedShipment"&&c.RecordType=="Shipment"&&c.ShipmentId==pendingShipment&&c.Status=="Packed");
  Assert.Contains(view.Snapshot.Capture.Links,link=>link.Evidence.Type=="InstanceLink"&&link.Evidence.Relationship=="Split");Assert.Contains(view.Snapshot.Capture.Links,link=>link.Evidence.Type=="InventoryTransaction"&&link.Evidence.Relationship=="ActualIssueToOrder");Assert.Empty(view.Assessments);Assert.Empty(view.HoldLinks);
  var candidate=Assert.Single(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Shipment"&&c.ShipmentId==shipment);var proposal=Id(await plant.Ok(plant.Engineer,$"{Api}/trace/{id}/assessments",new{expectedVersion=1,snapshotNumber=1,candidateKey=candidate.Key,decision="PotentiallyAffected",basis="Human reviewed exact recorded shipment and potential scope",evidence="Actual trace paths reviewed; defect not inferred",plannedDisposition="Human customer/containment review; no automatic notification",reason="Human proposed impact"}));
  await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People["eng"]}/roles",new{role=Roles.QualityManager,reason="Approval possession does not bypass proposer independence"});await Reject(plant,plant.Engineer,$"{Api}/assessments/{proposal}/approve",new{expectedVersion=1,reason="Self approval denied"},"separation_of_duties");await plant.Ok(plant.Approver,$"{Api}/assessments/{proposal}/approve",new{expectedVersion=1,reason="Independent actual scope/impact review"});
  var hold=Id(await plant.Ok(plant.Engineer,"/api/holds/",new{kind="Quality",targetType="Shipment",targetId=shipment.ToString(CultureInfo.InvariantCulture),source="Actual trace investigation "+id,evidence="Independent approved candidate review",requiredResolution="Human Quality resolution and separate governed hold release",reason="Actual human containment decision"}));await plant.Ok(plant.Engineer,$"{Api}/trace/{id}/hold-links",new{expectedVersion=1,assessmentId=proposal,expectedAssessmentVersion=2,holdId=hold,expectedHoldVersion=1,basis="Exact current approved candidate and active actual hold",reason="Record actual containment linkage"});
  var before=await Stored(app,"quality.trace_snapshot","investigation_id",id);Assert.Equal(result.GetRawText(),(await Json(await plant.Engineer.CommandAsync(Api+"/trace",body,"actual-supplier-case"))).GetRawText());Assert.Equal(before,await Stored(app,"quality.trace_snapshot","investigation_id",id));
  await plant.Ok(plant.Engineer,$"{Api}/trace/{id}/refresh",new{expectedVersion=1,reason="Retained later actual owner snapshot"});var refreshed=await View(plant.Engineer,id);Assert.Equal(2,refreshed.Header.LatestSnapshot);Assert.Equal(view.Snapshot.Capture.SourceFingerprint,(await View(plant.Engineer,id,1)).Snapshot.Capture.SourceFingerprint);
  await Reject(plant,plant.Approver,$"{Api}/trace/{id}/close",new{expectedVersion=2,acknowledgedGaps=false,basis="An unknown physical binding is not silently treated as complete",reason="Explicit gaps required"},"trace_gaps_unacknowledged");
  foreach(var item in refreshed.Snapshot.Capture.Candidates)
  {var assessment=Id(await plant.Ok(plant.Engineer,$"{Api}/trace/{id}/assessments",new{expectedVersion=2,snapshotNumber=2,candidateKey=item.Key,decision="Undetermined",basis="Human reviewed exact recorded candidate; physical impact not proven",evidence="Actual retained snapshot paths and documented unknowns",plannedDisposition="Retain documented uncertainty; existing shipment hold remains governed separately",reason="Explicit human candidate assessment"}));await plant.Ok(plant.Approver,$"{Api}/assessments/{assessment}/approve",new{expectedVersion=1,reason="Independent current actual candidate/gap review"});}
  await plant.Ok(plant.Approver,$"{Api}/trace/{id}/close",new{expectedVersion=2,acknowledgedGaps=true,basis="Every retained candidate independently reviewed; physical unknowns explicitly acknowledged and hold authority remains separate",reason="Human close of investigation record only"});Assert.Equal(TraceInvestigationState.Closed,(await View(plant.Engineer,id)).Header.State);
  var holds=await plant.Engineer.GetFromJsonAsync<JsonElement>("/api/holds/?includeReleased=true");Assert.True(Assert.Single(holds.EnumerateArray(),h=>h.GetProperty("holdId").ValueKind==JsonValueKind.Number&&h.GetProperty("holdId").GetInt64()==hold).GetProperty("active").GetBoolean());
 }
 [Fact]
 public async Task Actual_failed_calibration_records_reviewed_interval_and_potential_shipment_without_rewriting_passing_measurement_or_declaring_defect()
 {
  await using var app=new ForgeApp(await postgres.CreateDatabaseAsync(),configureBuilder:builder=>builder.UseSetting(QmsService.ConfigurationKey,"EXAMPLE-ORG"));var(plant,_,shipment,inspectionId,_)=await Source(app,true);Assert.NotNull(inspectionId);var original=await Stored(app,"quality.inspection","inspection_id",inspectionId.Value);var originalResults=await Stored(app,"quality.inspection_result","inspection_id",inspectionId.Value);
  var inspections=await plant.Engineer.GetFromJsonAsync<Forge.Quality.Contracts.InspectionInfo[]>("/api/quality/inspections?take=1000",CanonicalJson.Options);var inspection=Assert.Single(inspections!,record=>record.InspectionId==inspectionId);
  await plant.Ok(plant.Engineer,"/api/resources/tools/TRACE-GAUGE/calibrations",new{calibratedOn=Day(0),passed=false,dueOn=Day(1),certificate="Actual failed as-found verification",reason="Observed later measuring resource concern"});var events=await plant.Engineer.GetFromJsonAsync<ToolEvent[]>("/api/resources/tools/TRACE-GAUGE/history",CanonicalJson.Options);var failure=Assert.Single(events!,entry=>entry.Kind==ToolEventKind.CalibrationFailed);
  var content=new MeasurementFindingContent("TRACE-GAUGE",failure.EventId,DateTimeOffset.UtcNow,"Actual failed as-found observation",new("Width","mm",9,11,"Quality's actual suspected measurement range"),inspection.At,failure.At,"Human reviewed interval from actual product measurement through observed failed verification","Actual failure certificate and retained measurement references");
  var finding=Id(await plant.Ok(plant.Engineer,Api+"/measurement-findings",new{content,reason="Human observation; no automatic product defect"}));await plant.Ok(plant.Engineer,$"{Api}/measurement-findings/{finding}/submit",new{expectedVersion=1,reason="Submit exact observation and suspected interval"});await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People["eng"]}/roles",new{role=Roles.QualityManager,reason="Role cannot bypass original finding author"});await Reject(plant,plant.Engineer,$"{Api}/measurement-findings/{finding}/approve",new{expectedVersion=2,reason="Self interval approval denied"},"separation_of_duties");await plant.Ok(plant.Approver,$"{Api}/measurement-findings/{finding}/approve",new{expectedVersion=2,reason="Independent actual interval/observation review"});
  await Reject(plant,plant.Engineer,$"{Api}/measurement-findings/{finding}/edit",new{expectedVersion=3,content=content with{SuspectedFrom=null},reason="Reviewed interval is immutable"},"finding_immutable");
  var id=Id(await plant.Ok(plant.Engineer,Api+"/trace",new{root=new TraceInvestigationRoot(TraceTriggerKind.MeasurementFinding,null,null,finding),title="Actual gauge impact investigation",ownerPersonId=plant.People["eng"],triggerEvidence="Reviewed failed gauge observation and historical product measurement",reason="Human trace review required before any defect/disposition"}));var view=await View(plant.Engineer,id);
  Assert.True(view.Snapshot.Capture.Completeness.IntervalKnown);Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Inspection"&&c.RecordId==inspectionId.Value.ToString(CultureInfo.InvariantCulture)&&c.Status=="Pass");Assert.Contains(view.Snapshot.Capture.Candidates,c=>c.RecordType=="Shipment"&&c.ShipmentId==shipment);Assert.Contains(view.Snapshot.Capture.Completeness.Gaps,g=>g.Code=="legacy_measurement_coverage_unknown");Assert.Empty(view.Assessments);Assert.Empty(view.HoldLinks);
  var retained=Assert.Single(view.Snapshot.Capture.Links,link=>link.Evidence.Relationship=="RecordedGaugeInspection").Evidence;Assert.NotNull(retained.CapturedCanonicalJson);using(var raw=JsonDocument.Parse(retained.CapturedCanonicalJson)){Assert.Equal(inspectionId,raw.RootElement.GetProperty("inspectionId").GetInt64());Assert.Equal(10,Assert.Single(raw.RootElement.GetProperty("results").EnumerateArray()).GetProperty("measured").GetDecimal());}
  Assert.Equal(original,await Stored(app,"quality.inspection","inspection_id",inspectionId.Value));Assert.Equal(originalResults,await Stored(app,"quality.inspection_result","inspection_id",inspectionId.Value));
 }
 [Fact]
 public async Task Current_private_downstream_source_revocation_projects_explicit_partial_trace_and_preserves_retained_snapshot_bytes()
 {
  await using var app=new ForgeApp(await postgres.CreateDatabaseAsync(),configureBuilder:builder=>builder.UseSetting(QmsService.ConfigurationKey,"EXAMPLE-ORG"));var(plant,order,shipment,_,program)=await Source(app,privateOutput:true);Assert.NotNull(program);
  var id=Id(await plant.Ok(plant.Engineer,Api+"/trace",new{root=new TraceInvestigationRoot(TraceTriggerKind.SupplierLot,"TRACE-RAW","MASTER",null),title="Private downstream canary TRACE-OUTPUT",ownerPersonId=plant.People["eng"],triggerEvidence="Recorded private order "+order+" and customer shipment "+shipment,reason="Authorized actual complete source capture"}));var before=await Stored(app,"quality.trace_snapshot","investigation_id",id);var initial=await View(plant.Engineer,id);Assert.Contains(initial.Snapshot.Capture.Candidates,c=>c.ShipmentId==shipment);
  await plant.Ok(plant.Admin,$"/api/kernel/people/{plant.People["eng"]}/programs/{program}/revoke",new{reason="Withdraw actual private downstream source membership"});var projected=await View(plant.Engineer,id);Assert.True(projected.NarrativeRedacted);Assert.True(projected.Snapshot.Capture.Completeness.RestrictedSources);Assert.False(projected.Snapshot.Capture.Completeness.RecordedTraversalComplete);Assert.DoesNotContain(projected.Snapshot.Capture.Candidates,c=>c.OrderNumber==order||c.ShipmentId==shipment||c.PartNumber=="TRACE-OUTPUT");Assert.DoesNotContain("TRACE-OUTPUT",JsonSerializer.Serialize(projected),StringComparison.Ordinal);Assert.DoesNotContain("Recorded actual customer",JsonSerializer.Serialize(projected),StringComparison.Ordinal);Assert.Equal(before,await Stored(app,"quality.trace_snapshot","investigation_id",id));
  var hidden=Assert.Single(initial.Snapshot.Capture.Candidates,c=>c.RecordType=="Shipment"&&c.ShipmentId==shipment);await Reject(plant,plant.Engineer,$"{Api}/trace/{id}/assessments",new{expectedVersion=1,snapshotNumber=1,candidateKey=hidden.Key,decision="Undetermined",basis="Cannot replace current source membership with saved evidence",evidence="Retained snapshot does not grant current access",plannedDisposition="Require authorized reviewer",reason="Source revoked before action"},"program",HttpStatusCode.Forbidden);
 }
}


